const isNodeMatchingSelectorFocusable = function (options, node) {
  if (
    node.disabled ||
    isHiddenInput(node) ||
    isHidden(node, options.displayCheck) ||
    /* For a details element with a summary, the summary element gets the focused  */
    isDetailsWithSummary(node) ||
    isInDisabledFieldset(node)
  ) {
    return false;
  }
  return true;
};

const isInDisabledFieldset = function (node) {
  // Form controls inside a disabled fieldset are not focusable,
  // except those in the fieldset's first legend.
  const fieldset = node.closest('fieldset[disabled]');
  if (!fieldset) {
    return false;
  }
  const legend = fieldset.querySelector('legend');
  if (legend && legend.contains(node)) {
    return false;
  }
  return true;
};
